 $check=$pdo->prepare('SELECT id_detail FROM detail_progress WHERE id_detail=? AND id_progress=?');$upd=$pdo->prepare('UPDATE detail_progress SET kecamatan=?,desa=?,sls=?,sub_sls=?,jam_mulai=?,jam_selesai=?,uraian_kegiatan=?,permasalahan=?,pemecahan_masalah=?,output_tujuan=? WHERE id_detail=? AND id_progress=?');$ins=$pdo->prepare('INSERT INTO detail_progress(id_progress,kecamatan,desa,sls,sub_sls,jam_mulai,jam_selesai,uraian_kegiatan,permasalahan,pemecahan_masalah,output_tujuan) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$doc=$pdo->prepare('INSERT INTO dokumentasi(id_detail,nama_file,path_file,keterangan) VALUES(?,?,?,?)');$kept=[];
